    function setRay(e){var b=canvas.getBoundingClientRect();pointer.set((e.clientX-b.left)/b.width*2-1,-(e.clientY-b.top)/b.height*2+1);host.world.updateMatrixWorld(true);ray.setFromCamera(pointer,host.camera);}
