    function target(p){if(!p)return null;var center=host.panPosition();if(Math.hypot(p.x-center.x,p.z-center.z)<.76)return 'pan';if(Math.hypot(p.x+1.1,p.z+.45)<.64)return 'pot';return null;}
    function snapshot(objects){return objects.map(function(o){return {object:o,position:o.position.clone(),rotation:o.rotation.clone()};});}
    function restore(g){if(g&&g.original)g.original.forEach(function(o){o.object.position.copy(o.position);o.object.rotation.copy(o.rotation);});}
    canvas.dataset.discoveryTarget='';canvas.dataset.discoveryReady='';
    function clearStart(){if(!startCue)return;startCue=null;canvas.dataset.discoveryTarget='';canvas.dataset.discoveryReady='';if(shelf)shelf.start(null);}
    function updateDiscovery(){if(!startCue||!shelf)return;var point=new T.Vector3(startCue.point.x,startCue.point.y,startCue.point.z).project(host.camera),w=canvas.clientWidth,h=canvas.clientHeight;shelf.position({x:(point.x+1)*w/2,y:(1-point.y)*h/2,visible:point.z>=-1&&point.z<=1&&Math.abs(point.x)<.94&&Math.abs(point.y)<.94});}
    function findStart(){if(disposed||host.locked()||tool==='camera')return;cancel();host.pause();var info=root.KitchenDiscovery.find(host.getState(),tool,{locked:host.locked(),scale:host.scaleInfo(),oil:host.oilInfo(),checkTimers:host.getCheckTimers()});if(!info)return;host.frameTool(tool);if(tool==='move')host.frameDiscovery(info.hit);$('recipeScene').scrollIntoView({block:'nearest'});var point=host.highlightTarget(info.hit,info.ready);if(!point)return;startCue={point:point,state:host.getState()};canvas.dataset.discoveryTarget=JSON.stringify(info.hit);canvas.dataset.discoveryReady=String(info.ready);shelf.start(info);updateDiscovery();host.draw();}
    function clearHover(){hoverKey=null;if(shelf)shelf.hover(null);host.highlightTarget(null);}
